import sys

def isPerfect(num):
    if num <= 1:
        return 0
    total = 0
    for i in range(1, num):
        if num % i == 0:
            total += i
    return 1 if total == num else 0

def main():
    data = sys.stdin.read().strip()
    if not data:
        return
    try:
        num = int(data)
    except ValueError:
        return
    if isPerfect(num):
        print("Perfect")
    else:
        print("Not Perfect")

if __name__ == "__main__":
    main()
